mapper.select:
SELECT CURRENT_STATENO "stateno", EHARS_STATENO, NYC_STATENO, NYC_CITYNO, NON_CASE_FLAG, REASON_DESC, REQUEST_COMMENTS, usr1.LAST_NAME || ', ' || usr1.FIRST_NAME FLAGGED_BY, TO_CHAR(FLAGGED_DATE, 'MM/DD/YYYY') FLAGGED_DATE, REVIEW_COMMENTS, case when noncase.LAST_UPDATED_BY is not null then usr2.LAST_NAME || ', ' || usr2.FIRST_NAME else null end LAST_UPDATED_BY, TO_CHAR(noncase.LAST_UPDATED_DATE, 'MM/DD/YYYY') LAST_UPDATED_DATE FROM NYEHMS_NONCASE_STATENOS noncase, CODED_NON_CASE_REASON reason, NYEHMS_USERS usr1, NYEHMS_USERS usr2 where noncase.reason_code = reason.reason_code and noncase.flagged_by = usr1.worker_id(+) and noncase.last_updated_by = usr2.worker_id(+) and NON_CASE_FLAG = #{ACTIVE_FLAG}
and FLAGGED_DATE between FN_TO_DATE(#{FROM_DATE}, 'MM/DD/YYYY') and FN_TO_DATE(#{TO_DATE}, 'MM/DD/YYYY')+1
order by CURRENT_STATENO, flagged_Date asc
